application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap');

:root { --ink:#17212b; --muted:#6d7782; --line:#dce3e8; --cream:#f6f8f7; --mint:#dff3e9; --green:#147d61; --dark:#123b35; --coral:#ef756c; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; background:var(--cream); color:var(--ink); font-family:'DM Sans',sans-serif; }
.app-shell { max-width:1120px; margin:0 auto; padding:48px 28px 28px; }
.hero { display:flex; justify-content:space-between; align-items:center; background:var(--dark); color:white; border-radius:24px; padding:50px 58px; overflow:hidden; position:relative; }
.hero:after { content:''; position:absolute; width:300px; height:300px; border:1px solid rgba(255,255,255,.13); border-radius:50%; right:-80px; top:-130px; box-shadow:0 0 0 35px rgba(255,255,255,.04),0 0 0 70px rgba(255,255,255,.03); }
.eyebrow { color:#67c5a2; text-transform:uppercase; letter-spacing:.14em; font-size:11px; font-weight:700; margin:0 0 12px; }
.hero h1 { font:700 42px 'Playfair Display',serif; margin:0 0 12px; letter-spacing:-.02em; }
.intro { color:#c4d5d0; max-width:480px; line-height:1.6; margin:0; }
.hero-mark { color:#72d2ad; font-size:80px; transform:rotate(20deg); margin-right:55px; position:relative; z-index:1; }
.workspace { display:grid; grid-template-columns:1fr 1fr; gap:24px; margin-top:24px; }
.booking-form,.booking-panel { background:white; border:1px solid #e7ecef; border-radius:20px; padding:30px; box-shadow:0 7px 20px rgba(27,47,58,.04); }
.section-heading { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:25px; }
.section-heading h2 { font:700 25px 'Playfair Display',serif; margin:0; }
.required-note { color:var(--muted); font-size:12px; margin-top:9px; }
.field-grid { display:grid; grid-template-columns:1fr 1fr; gap:18px 15px; }
.field { display:flex; flex-direction:column; gap:8px; font-size:13px; font-weight:600; }
.field-wide { grid-column:span 2; }
.field b { color:var(--coral); }
input,select { width:100%; border:1px solid var(--line); border-radius:9px; padding:12px 13px; color:var(--ink); background:#fbfcfc; font:400 14px 'DM Sans',sans-serif; outline:none; transition:.2s; }
input:focus,select:focus { border-color:var(--green); box-shadow:0 0 0 3px rgba(20,125,97,.12); }
.primary-button { margin-top:25px; width:100%; border:0; border-radius:10px; padding:14px; color:white; background:var(--green); font:700 14px 'DM Sans',sans-serif; cursor:pointer; transition:.2s; }
.primary-button:hover { background:#0e684f; transform:translateY(-1px); }
.primary-button span { margin-left:7px; font-size:18px; vertical-align:-1px; }
.form-error { color:#c3544c; font-size:12px; min-height:16px; margin:13px 0 -4px; }
.count-badge { background:var(--mint); color:var(--green); border-radius:20px; min-width:30px; padding:6px 10px; text-align:center; font-size:12px; font-weight:700; }
.confirmation { background:#e6f6ef; color:#17664f; border-radius:9px; padding:12px 14px; font-size:13px; margin:-5px 0 16px; }
.booking-list { display:flex; flex-direction:column; gap:12px; }
.empty-state { text-align:center; border:1px dashed var(--line); border-radius:12px; padding:32px 15px; color:var(--muted); }
.empty-icon { color:#8bcdb5; font-size:30px; margin-bottom:8px; }
.empty-state h3 { color:var(--ink); font-size:15px; margin:0 0 5px; }
.empty-state p { font-size:12px; margin:0; }
.booking-card { border:1px solid var(--line); border-left:4px solid var(--green); border-radius:11px; padding:16px; position:relative; }
.booking-card.cancelled { border-left-color:#aeb7bd; opacity:.62; }
.booking-top { display:flex; justify-content:space-between; gap:12px; align-items:start; }
.booking-name { font-size:16px; font-weight:700; margin:0 0 5px; }
.booking-type { color:var(--green); font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.06em; }
.booking-meta { color:var(--muted); font-size:12px; margin:14px 0 0; }
.cancel-button { border:0; background:none; color:#c25f58; font:600 11px 'DM Sans',sans-serif; cursor:pointer; padding:3px; }
.cancel-button:disabled { color:var(--muted); cursor:default; }
.status-label { color:var(--muted); font-size:11px; font-weight:700; text-transform:uppercase; }
footer { text-align:center; color:#89939a; font-size:11px; margin-top:22px; }
@media (max-width:760px) { .app-shell{padding:20px 15px}.hero{padding:35px 28px}.hero h1{font-size:32px}.hero-mark{display:none}.workspace{grid-template-columns:1fr}.booking-form,.booking-panel{padding:23px} }
@media (max-width:430px) { .field-grid{grid-template-columns:1fr}.field-wide{grid-column:auto} }

application.javascript:
const form = document.getElementById('booking-form');
const dateInput = document.getElementById('booking-date');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const confirmation = document.getElementById('confirmation');
const error = document.getElementById('form-error');
const count = document.getElementById('booking-count');

const today = new Date();
const localToday = new Date(today.getTime() - today.getTimezoneOffset() * 60000).toISOString().split('T')[0];
dateInput.min = localToday;
let bookings = [];

function formatDate(value) {
  return new Date(value + 'T00:00:00').toLocaleDateString(undefined, {weekday:'short', month:'short', day:'numeric', year:'numeric'});
}

function render() {
  list.querySelectorAll('[data-testid="booking"]').forEach(card => card.remove());
  emptyState.hidden = bookings.length > 0;
  count.textContent = bookings.filter(item => !item.cancelled).length;
  bookings.forEach(item => {
    const card = document.createElement('article');
    card.className = 'booking-card' + (item.cancelled ? ' cancelled' : '');
    card.dataset.testid = 'booking';
    card.dataset.status = item.cancelled ? 'cancelled' : 'active';
    const top = document.createElement('div');
    top.className = 'booking-top';
    const details = document.createElement('div');
    const name = document.createElement('h3');
    name.className = 'booking-name';
    name.dataset.testid = 'booking-name-display';
    name.textContent = item.name;
    const type = document.createElement('div');
    type.className = 'booking-type';
    type.textContent = item.type;
    details.append(name, type);
    const cancel = document.createElement('button');
    cancel.type = 'button';
    cancel.className = 'cancel-button';
    cancel.dataset.testid = 'booking-cancel';
    cancel.textContent = item.cancelled ? 'Cancelled' : 'Cancel';
    cancel.disabled = item.cancelled;
    cancel.addEventListener('click', () => { item.cancelled = true; render(); });
    top.append(details, cancel);
    const meta = document.createElement('p');
    meta.className = 'booking-meta';
    meta.textContent = formatDate(item.date) + '  •  ' + item.time;
    card.append(top, meta);
    list.append(card);
  });
}

form.addEventListener('submit', event => {
  event.preventDefault();
  error.textContent = '';
  if (!form.checkValidity()) { form.reportValidity(); return; }
  if (dateInput.value < localToday) { error.textContent = 'Please choose today or a future date.'; dateInput.focus(); return; }
  const data = new FormData(form);
  bookings.push({name:data.get('name'), email:data.get('email'), date:data.get('date'), time:data.get('time'), type:data.get('type'), cancelled:false});
  render();
  confirmation.textContent = 'Booking confirmed for ' + data.get('name') + ' on ' + formatDate(data.get('date')) + '.';
  confirmation.hidden = false;
  form.reset();
  dateInput.min = localToday;
});

render();

