<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Appointment Booking</title>
  <link rel="stylesheet" href="styles.css">
  <script src="script.js" defer></script>
</head>
<body>
  <main class="app-shell">
    <section class="hero">
      <div class="hero-copy">
        <p class="eyebrow">Simple scheduling</p>
        <h1>Plan your next appointment.</h1>
        <p class="intro">Choose a convenient time and keep your upcoming visits organized in one place.</p>
      </div>
      <div class="hero-mark" aria-hidden="true">✦</div>
    </section>

    <section class="workspace">
      <form id="booking-form" class="booking-form">
        <div class="section-heading">
          <div>
            <p class="eyebrow">New booking</p>
            <h2>Appointment details</h2>
          </div>
          <span class="required-note">* Required</span>
        </div>

        <div class="field-grid">
          <label class="field field-wide">
            <span>Customer name <b>*</b></span>
            <input data-testid="booking-name" id="booking-name" name="name" type="text" placeholder="e.g. Jordan Lee" autocomplete="name" required>
          </label>
          <label class="field field-wide">
            <span>Email address <b>*</b></span>
            <input data-testid="booking-email" id="booking-email" name="email" type="email" placeholder="jordan@example.com" autocomplete="email" required>
          </label>
          <label class="field">
            <span>Appointment date <b>*</b></span>
            <input data-testid="booking-date" id="booking-date" name="date" type="date" required>
          </label>
          <label class="field">
            <span>Appointment time <b>*</b></span>
            <input data-testid="booking-time" id="booking-time" name="time" type="time" required>
          </label>
          <label class="field field-wide">
            <span>Appointment type <b>*</b></span>
            <select data-testid="booking-type" id="booking-type" name="type" required>
