              <option>Consultation</option>
              <option>Follow-up</option>
              <option>Routine check-in</option>
              <option>Project discussion</option>
            </select>
          </label>
        </div>
        <p id="form-error" class="form-error" role="alert" aria-live="polite"></p>
        <button data-testid="booking-submit" class="primary-button" type="submit">Create booking <span aria-hidden="true">→</span></button>
      </form>

      <section class="booking-panel" aria-labelledby="bookings-title">
        <div class="section-heading list-heading">
          <div>
            <p class="eyebrow">Your schedule</p>
            <h2 id="bookings-title">Bookings</h2>
          </div>
          <span id="booking-count" class="count-badge">0</span>
